    ["Thanks for calling {name} in {town}! / We're open ten to ten, seven days a week. / Leave a message and we'll call you right back."] = "Obrigado por ligar para {name} em {town}! / Funcionamos das dez às dez, sete dias por semana. / Deixe uma mensagem e retornaremos logo.",
    ["You've reached {name}. / Our hours are nine to seven. For a refill, leave your name and prescription number after the tone."] = "Você ligou para {name}. / Nosso horário é das nove às sete. Para reposição de receita, deixe seu nome e o número da receita após o sinal.",
    ["Thank you for calling {name}. / Sunday service is at ten. / Leave a message and the pastor will call you back."] = "Obrigado por ligar para {name}. / O culto de domingo é às dez. / Deixe uma mensagem e o pastor retornará a ligação.",
    ["You've reached {name}. / If this is an emergency, hang up and dial nine-one-one. / Otherwise leave a message."] = "Você ligou para {name}. / Se for uma emergência, desligue e disque nove um um. / Caso contrário, deixe uma mensagem.",
    ["You've reached {name}. / School is out for the summer. The office is open Tuesdays and Thursdays."] = "Você ligou para {name}. / A escola está de férias de verão. A secretaria abre às terças e quintas.",
    ["{name}. We're open eight to six, closed Sundays. / Leave a message."] = "{name}. Funcionamos das oito às seis, fechado aos domingos. / Deixe uma mensagem.",
    ["{name}. We're open twenty-four hours. / Leave a message for the manager."] = "{name}. Funcionamos vinte e quatro horas. / Deixe uma mensagem para o gerente.",
    ["You've reached {name}. / Because of the emergency we are closed until further notice. / Please don't come by. Stay safe."] = "Você ligou para {name}. / Por causa da emergência, estamos fechados até novo aviso. / Por favor, não venham. Fiquem em segurança.",
    ["This is {name}. / We are out of antibiotics and fever reducers. / If you are sick, do not come to the pharmacy. Stay home."] = "Aqui é {name}. / Estamos sem antibióticos e sem antitérmicos. / Se você está doente, não venha à farmácia. Fique em casa.",
    ["This is {name}. / The fellowship hall is open to anyone who needs somewhere to go. / Come to the side door and knock. We'll let you in."] = "Aqui é {name}. / O salão da comunidade está aberto a quem precisar de um lugar para ir. / Venha até a porta lateral e bata. Vamos deixar você entrar.",
    ["You've reached {name}. / Deputies cannot respond to calls that are not emergencies. / Stay inside and keep your doors locked."] = "Você ligou para {name}. / Os policiais não podem atender chamadas que não sejam emergências. / Fique dentro de casa e mantenha as portas trancadas.",
    ["This is {name}. / The building is being used by the county. / Please do not come to the school. Please."] = "Aqui é {name}. / O prédio está sendo usado pelo condado. / Por favor, não venham à escola. Por favor.",
    ["{name}. / We're out of plywood, nails and generators. / We're closing early until this is over."] = "{name}. / Estamos sem compensado, pregos e geradores. / Vamos fechar mais cedo até isso acabar.",
    ["{name}. / No gas until the truck comes. We don't know when the truck comes."] = "{name}. / Sem gasolina até o caminhão chegar. Não sabemos quando o caminhão chega.",
    ["Nine-one-one, please hold. / All of our dispatchers are on other calls. / Please stay on the line. Do not hang up."] = "Nove um um, aguarde, por favor. / Todos os nossos atendentes estão em outras chamadas. / Por favor, continue na linha. Não desligue.",
    ["You have reached Knox County Emergency Communications. / Because of the number of calls, units cannot be sent to every address. / Stay inside. Lock your doors. Do not go near anyone who is sick."] = "Você ligou para as Comunicações de Emergência do Condado de Knox. / Devido ao número de chamadas, não é possível enviar equipes a todos os endereços. / Fique dentro de casa. Tranque as portas. Não se aproxime de ninguém que esteja doente.",
    ["This is a recorded message from the Kentucky Division of Emergency Management. / Emergency services in the Knox County area are suspended. / Shelter in place. Listen to the Emergency Broadcast System for instructions."] = "Esta é uma mensagem gravada da Divisão de Gerenciamento de Emergências do Kentucky. / Os serviços de emergência na região do Condado de Knox estão suspensos. / Permaneça abrigado. Ouça o Sistema de Transmissão de Emergência para instruções.",
    ["Thank you for calling the Kentucky public information line. / If someone in your home has a fever or has been bitten, keep them in a separate room. / Do not travel. Checkpoints are in place on 31W and the interstate."] = "Obrigado por ligar para a linha de informações públicas do Kentucky. / Se alguém em sua casa tem febre ou foi mordido, mantenha a pessoa em um cômodo separado. / Não viaje. Há bloqueios na 31W e na interestadual.",
    ["This is the Kentucky public information line. / The Knox County exclusion zone is closed. No one will be allowed to leave. / Do not approach the fence. This message will be updated."] = "Esta é a linha de informações públicas do Kentucky. / A zona de exclusão do Condado de Knox está fechada. Ninguém poderá sair. / Não se aproxime da cerca. Esta mensagem será atualizada.",
    ["Kentucky info line"] = "Linha de informações do Kentucky",
    ["Directory assistance is not available at this time. / Please try your call again later."] = "A lista telefônica não está disponível no momento. / Por favor, tente ligar novamente mais tarde.",
    ["Directory assistance. What city, please?"] = "Informações telefônicas. De qual cidade, por favor?",
